740	export async function processApiResponse(
741	  data: any,
742	  prompt: string,
743	  responseFormat: string,
744	  cached: boolean,
745	  model: string,
746	  size: string,
747	  latencyMs?: number,
748	  quality?: string,
749	  n: number = 1,
750	  outputFormat?: string,
751	  billingConfig: OpenAiImageOptions = {},
752	): Promise<ProviderResponse> {
753	  if (data.error) {
754	    await data?.deleteFromCache?.();
755	    return {
756	      error: formatOpenAiError(data),
757	    };
758	  }
759	
760	  try {
761	    const formattedOutput = formatOutput(data, prompt, responseFormat, outputFormat);
762	    if (typeof formattedOutput === 'object') {
763	      return formattedOutput;
764	    }
765	
766	    const exactUsageCost = calculateOpenAIUsageCost(model, billingConfig, data.usage, {
767	      cachedResponse: cached,
768	    });
769	    const cost = exactUsageCost ?? (cached ? 0 : calculateImageCost(model, size, quality, n));
770	    const tokenUsage = getImageTokenUsage(data, cached);
771	    const images = buildStructuredImageOutputs(data, outputFormat);
772	
773	    return {
774	      output: formattedOutput,
775	      images,
776	      cached,
777	      latencyMs,
778	      ...(cost === undefined ? {} : { cost }),
779	      ...(tokenUsage ? { tokenUsage } : {}),
780	      ...(data.usage ? { metadata: { usage: data.usage } } : {}),
781	      ...(responseFormat === 'b64_json' ? { isBase64: true, format: 'json' } : {}),
782	    };
783	  } catch (err) {
784	    await data?.deleteFromCache?.();
785	    return {
786	      error: `API error: ${String(err)}: ${JSON.stringify(data)}`,
787	    };
788	  }
789	}
